// ===== CONFIGURACIÓN (edita aquí) =====
const RESPONSABLE = { id: 2, nombre: 'Nombre del area administrativa' }; // ID de usuario en el sistema: a quien se le asigna la tarea
const AVISAR_A = { nombre: 'Tu nombre', email: 'tu-correo@equiterm.com' };      // a quien le llega el aviso de cada correo entrante
const IGNORAR_REMITENTES = /(no-?reply|noreply|mailer-daemon|postmaster|notifications?@|@equiterm\.)/i;
const SOLO_SI_ASUNTO_O_TEXTO_CONTIENE = null; // ej: /cotiz|precio|caldera|presupuesto/i  (null = todos los correos)
// ======================================

const j = $json;
const fromObj = (j.from && j.from.value && j.from.value[0]) || {};
const email = (fromObj.address || '').trim().toLowerCase();
const name = (fromObj.name || '').trim();
const subject = (j.subject || '').trim();
const body = (j.textPlain || j.text || '').replace(/\s+\n/g, '\n').trim().slice(0, 5000);
const messageId = (j.messageId || j.headers?.['message-id'] || (email + '|' + subject + '|' + (j.date || ''))).toString();

const autoReply = /auto(matic)?[- ]?(reply|respuesta)|out of office|fuera de la oficina/i.test(subject);
let valido = !!email && !IGNORAR_REMITENTES.test(email) && !autoReply;
if (valido && SOLO_SI_ASUNTO_O_TEXTO_CONTIENE) valido = SOLO_SI_ASUNTO_O_TEXTO_CONTIENE.test(subject + ' ' + body);

const vendedor = valido ? { ...AVISAR_A, responsable: RESPONSABLE.nombre } : null;

return {
  json: {
    valido,
    vendedor,
    payload: {
      message_id: messageId,
      email,
      name: name || null,
      subject,
      message: body,
      received_at: j.date ? new Date(j.date).toISOString() : new Date().toISOString(),
      assigned_to: valido ? RESPONSABLE.id : null,
      create_task: true,
    },
  },
};
